import{_ as e,o as d,c as r,a4 as a}from"./chunks/framework.YC5CMuPM.js";const p=JSON.parse('{"title":"Tutorials","description":"","frontmatter":{},"headers":[],"relativePath":"tutorials/index.md","filePath":"tutorials/index.md","lastUpdated":null}'),o={name:"tutorials/index.md"};function i(n,t,s,l,c,h){return d(),r("div",null,[...t[0]||(t[0]=[a('<h1 id="tutorials" tabindex="-1">Tutorials <a class="header-anchor" href="#tutorials" aria-label="Permalink to &quot;Tutorials&quot;">​</a></h1><p><strong>Fourteen guides that distil the tutorials at <a href="https://juce.com/learn/tutorials/" target="_blank" rel="noreferrer">https://juce.com/learn/tutorials/</a> into one page per topic, plus three original guides on Box2D physics and music (15 to 17).</strong> Multi-part tutorials are merged, prose is shortened, and code is updated for the JUCE version in this repository (for example <code>FontOptions</code> instead of the deprecated <code>Font</code> constructors, <code>ParameterID</code> for parameters, CMake-first project setup). For the full step-by-step walkthroughs, screenshots, demo projects, and exercises, use the originals.</p><p>The guides are adapted from the ISC-licensed <a href="https://github.com/juce-framework/JUCE-tutorials" target="_blank" rel="noreferrer">JUCE-tutorials</a> sources, Copyright (c) Raw Material Software Limited. See <a href="./notice.html">the attribution notice</a> for the attribution and licence text.</p><p>For API details, the headers are the reference: see the notes on finding documentation in the main <a href="https://github.com/juce-framework/JUCE/blob/master/README.md#api-documentation" target="_blank" rel="noreferrer">README</a>, and check <a href="https://github.com/juce-framework/JUCE/blob/master/BREAKING_CHANGES.md" target="_blank" rel="noreferrer">BREAKING_CHANGES.md</a> when moving code between versions.</p><h2 id="suggested-order" tabindex="-1">Suggested order <a class="header-anchor" href="#suggested-order" aria-label="Permalink to &quot;Suggested order&quot;">​</a></h2><table tabindex="0"><thead><tr><th>#</th><th>Guide</th><th>You will learn</th><th>Level</th></tr></thead><tbody><tr><td>01</td><td><a href="./01-getting-started.html">Getting started</a></td><td>Project types, CMake and Projucer, the application class, windows, the main component</td><td>Beginner</td></tr><tr><td>02</td><td><a href="./02-graphics-and-layout.html">Graphics, layout, and animation</a></td><td><code>Graphics</code>, nested components, <code>Rectangle</code>, <code>FlexBox</code>, <code>Grid</code>, colours, look and feel, animation</td><td>Beginner</td></tr><tr><td>03</td><td><a href="./03-widgets.html">Built-in widgets</a></td><td><code>Label</code>, <code>Slider</code>, <code>ComboBox</code>, buttons, <code>TableListBox</code></td><td>Beginner</td></tr><tr><td>04</td><td><a href="./04-listeners-and-state.html">Listeners, <code>ValueTree</code>, and undo</a></td><td>Broadcasting changes, data models, serialisation, <code>UndoManager</code></td><td>Beginner to intermediate</td></tr><tr><td>05</td><td><a href="./05-audio-io-and-playback.html">Audio input, output, files, and waveforms</a></td><td><code>AudioAppComponent</code>, devices, input processing, file playback, looping, thumbnails</td><td>Intermediate</td></tr><tr><td>06</td><td><a href="./06-synthesis.html">Synthesis</a></td><td>Noise, sine, levels and decibels, <code>Synthesiser</code>, wavetables</td><td>Intermediate</td></tr><tr><td>07</td><td><a href="./07-midi-and-mpe.html">MIDI and MPE</a></td><td><code>MidiMessage</code>, <code>MidiBuffer</code>, MIDI input, MPE zones and synthesis</td><td>Intermediate</td></tr><tr><td>08</td><td><a href="./08-plugin-basics.html">Audio plug-in basics</a></td><td>Processor and editor, MIDI plug-ins, bus layouts, packaging</td><td>Beginner to intermediate</td></tr><tr><td>09</td><td><a href="./09-plugin-parameters.html">Plug-in parameters and state</a></td><td>Parameters, <code>AudioProcessorValueTreeState</code>, attachments, saving state</td><td>Intermediate</td></tr><tr><td>10</td><td><a href="./10-audio-processor-graph.html">Cascading effects with <code>AudioProcessorGraph</code></a></td><td>Node graphs, dynamic effect chains, hosting processors</td><td>Advanced</td></tr><tr><td>11</td><td><a href="./11-dsp.html">DSP</a></td><td>Processor chains, filters, waveshaping, convolution, delay lines, FFT, SIMD</td><td>Intermediate to advanced</td></tr><tr><td>12</td><td><a href="./12-utilities.html">Core utilities</a></td><td><code>Random</code>, <code>BigInteger</code>, <code>File</code> and streams, OSC</td><td>Beginner to intermediate</td></tr><tr><td>13</td><td><a href="./13-opengl.html">Rendering with OpenGL</a></td><td><code>OpenGLAppComponent</code>, shaders, matrices</td><td>Advanced</td></tr><tr><td>14</td><td><a href="./14-mobile-and-app-services.html">Mobile and app services</a></td><td>Android setup and screen sizes, purchases, notifications, analytics, licensing</td><td>Intermediate to advanced</td></tr><tr><td>15</td><td><a href="./15-physics-music.html">Physics as a musical instrument</a></td><td><code>juce_box2d</code>, contact listeners, thread-safe hand-off to the audio thread, mapping collisions to notes</td><td>Intermediate to advanced</td></tr><tr><td>16</td><td><a href="./16-box2d-v3.html">Integrating Box2D v3</a></td><td><code>FetchContent</code>, ids instead of pointers, hit and sensor events, threading</td><td>Advanced</td></tr><tr><td>17</td><td><a href="./17-modal-physics-audio.html">A physical audio engine</a></td><td>Modal synthesis, contact-driven excitation, rolling noise, voice management, lock-free hand-off</td><td>Advanced</td></tr></tbody></table><h2 id="where-each-original-tutorial-went" tabindex="-1">Where each original tutorial went <a class="header-anchor" href="#where-each-original-tutorial-went" aria-label="Permalink to &quot;Where each original tutorial went&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Original tutorial (juce.com)</th><th>Guide</th></tr></thead><tbody><tr><td>Projucer Part 1, getting started with the Projucer</td><td>01</td></tr><tr><td>Projucer Part 2, manage your Projucer projects</td><td>01</td></tr><tr><td>Projucer Part 3, choosing the right Projucer template</td><td>01</td></tr><tr><td>The main component</td><td>01</td></tr><tr><td>The application window</td><td>01</td></tr><tr><td>The Graphics class</td><td>02</td></tr><tr><td>Parent and child components</td><td>02</td></tr><tr><td>The Point, Line, and Rectangle classes</td><td>02</td></tr><tr><td>Advanced GUI layout techniques</td><td>02</td></tr><tr><td>Responsive GUI layouts using FlexBox and Grid</td><td>02</td></tr><tr><td>Colours in JUCE</td><td>02</td></tr><tr><td>Customise the look and feel of your app</td><td>02</td></tr><tr><td>Animating geometry</td><td>02</td></tr><tr><td>The Label class</td><td>03</td></tr><tr><td>The Slider class</td><td>03</td></tr><tr><td>The ComboBox class</td><td>03</td></tr><tr><td>Radio buttons and checkboxes</td><td>03</td></tr><tr><td>The TableListBox class</td><td>03</td></tr><tr><td>Listeners and Broadcasters</td><td>04</td></tr><tr><td>The ValueTree class</td><td>04</td></tr><tr><td>Using an UndoManager with a ValueTree</td><td>04</td></tr><tr><td>The AudioDeviceManager class</td><td>05</td></tr><tr><td>Processing audio input</td><td>05</td></tr><tr><td>Build an audio player</td><td>05</td></tr><tr><td>Looping audio using the AudioSampleBuffer class</td><td>05</td></tr><tr><td>Looping audio using the AudioSampleBuffer class (advanced)</td><td>05</td></tr><tr><td>Draw audio waveforms</td><td>05</td></tr><tr><td>Build a white noise generator</td><td>06</td></tr><tr><td>Build a sine wave synthesiser</td><td>06</td></tr><tr><td>Control audio levels</td><td>06</td></tr><tr><td>Control audio levels using decibels</td><td>06</td></tr><tr><td>Build a MIDI synthesiser</td><td>06</td></tr><tr><td>Wavetable synthesis</td><td>06</td></tr><tr><td>Create MIDI data</td><td>07</td></tr><tr><td>Handling MIDI events</td><td>07</td></tr><tr><td>Build a multi-polyphonic synthesiser</td><td>07</td></tr><tr><td>Understanding MPE zones</td><td>07</td></tr><tr><td>Create a basic Audio/MIDI plugin, Part 1</td><td>08</td></tr><tr><td>Create a basic Audio/MIDI plugin, Part 2</td><td>08</td></tr><tr><td>Plugin examples</td><td>08</td></tr><tr><td>Configuring the right bus layouts for your plugins</td><td>08</td></tr><tr><td>Package your app or plugin for distribution</td><td>08</td></tr><tr><td>Adding plug-in parameters</td><td>09</td></tr><tr><td>Saving and loading your plug-in state</td><td>09</td></tr><tr><td>Cascading plug-in effects</td><td>10</td></tr><tr><td>Introduction to DSP</td><td>11</td></tr><tr><td>Add distortion through waveshaping and convolution</td><td>11</td></tr><tr><td>Create a string model with delay lines</td><td>11</td></tr><tr><td>The fast Fourier transform</td><td>11</td></tr><tr><td>Visualise the frequencies of a signal in real time</td><td>11</td></tr><tr><td>Optimisation using the SIMDRegister class</td><td>11</td></tr><tr><td>The Random class</td><td>12</td></tr><tr><td>The BigInteger class</td><td>12</td></tr><tr><td>File reading</td><td>12</td></tr><tr><td>Implement the OSC protocol in your app</td><td>12</td></tr><tr><td>Build an OpenGL application</td><td>13</td></tr><tr><td>Getting started with Android</td><td>14</td></tr><tr><td>Managing Android screen sizes</td><td>14</td></tr><tr><td>In-App Purchases on desktop and mobile devices</td><td>14</td></tr><tr><td>Push Notifications on desktop and mobile devices</td><td>14</td></tr><tr><td>App analytics collection</td><td>14</td></tr><tr><td>Unlock your plugins through online registration</td><td>14</td></tr></tbody></table><p>Guides 15 to 17 are written for this repository and have no juce.com original. The companion apps are <a href="https://github.com/juce-framework/JUCE/tree/master/examples/Box2DMusic" target="_blank" rel="noreferrer"><code>examples/Box2DMusic</code></a> (guide 15) and <a href="https://github.com/juce-framework/JUCE/tree/master/examples/Box2DAudioV3" target="_blank" rel="noreferrer"><code>examples/Box2DAudioV3</code></a> (guides 16 and 17).</p><h2 id="notes-on-the-examples" tabindex="-1">Notes on the examples <a class="header-anchor" href="#notes-on-the-examples" aria-label="Permalink to &quot;Notes on the examples&quot;">​</a></h2><ul><li>Code blocks are illustrative. They are written against this repository&#39;s JUCE version, but they are excerpts, so add the includes, <code>JUCE_DECLARE_NON_COPYABLE_WITH_LEAK_DETECTOR</code>, and remaining pure-virtual overrides that your own classes need. Complete, buildable programs live in <a href="https://github.com/juce-framework/JUCE/tree/master/examples" target="_blank" rel="noreferrer"><code>examples</code></a> and <a href="https://github.com/juce-framework/JUCE/tree/master/examples/CMake" target="_blank" rel="noreferrer"><code>examples/CMake</code></a>.</li><li>Real-time code (audio callbacks, MIDI callbacks, <code>render()</code> in OpenGL) runs off the message thread. Each guide flags the thread rules that apply.</li><li>Using JUCE requires compliance with its licence: see <a href="https://github.com/juce-framework/JUCE/blob/master/LICENSE.md" target="_blank" rel="noreferrer">LICENSE.md</a>. A commercial JUCE licence may be required for closed-source products.</li></ul>',11)])])}const m=e(o,[["render",i]]);export{p as __pageData,m as default};
